python3 - <<'EOF'
import json

# Load all 4 definitions
defs = {}
for name in ['end', 'decision', 'terminate', 'script']:
    with open(f'/tmp/def_{name}_compact.json') as f:
        defs[name] = json.load(f)

# Read the flow file
with open('/work/output/artifacts/skill-flow-ipe-enum/EnumTest/EnumTest/EnumTest.flow') as f:
    flow = json.load(f)

# Add the 4 definitions (check if not already present)
existing_types = {d['nodeType'] for d in flow['definitions']}
for name in ['end', 'decision', 'terminate', 'script']:
    nt = defs[name]['nodeType']
    if nt not in existing_types:
        flow['definitions'].append(defs[name])
        print(f'Added definition: {nt}')
    else:
        print(f'Already present: {nt}')

# Add variables.nodes for new nodes
existing_var_ids = {v['id'] for v in flow['variables']['nodes']}
new_vars = [
    {"id": "checkSuccess.output", "type": "object", "binding": {"nodeId": "checkSuccess", "outputId": "output"}},
    {"id": "logPassed.output", "type": "object", "binding": {"nodeId": "logPassed", "outputId": "output"}},
]
for v in new_vars:
    if v['id'] not in existing_var_ids:
        flow['variables']['nodes'].append(v)
        print(f'Added var: {v["id"]}')

# Add layout.nodes entries for new nodes
existing_layout = set(flow['layout']['nodes'].keys())
new_layout_nodes = ['checkSuccess', 'logPassed', 'endSuccess', 'terminateFailed']
for nid in new_layout_nodes:
    if nid not in existing_layout:
        flow['layout']['nodes'][nid] = {"position": {"x": 0, "y": 0}, "size": {"width": 96, "height": 96}, "collapsed": False}
        print(f'Added layout: {nid}')

# Write back
with open('/work/output/artifacts/skill-flow-ipe-enum/EnumTest/EnumTest/EnumTest.flow', 'w') as f:
    json.dump(flow, f, indent=2)
print('Flow written.')
EOF

